/**
 * IOS-12d (PC-L1, one Chat; Q1 (a), VF-PM 2026-11-06 19:12Z) — THE NEEDS-YOU CARD'S GOLDENS, generated by the Mac's
 * own card (`needs-card.ts`). Each case is a spark's entry as the card reads it (its id and name, the runs that are its
 * own session, its open items, oldest first) and the item it draws, in; the card's facts and its words, out. The
 * order a thread stands its cards in (`waitingCardOf`), what an answer came to (`needsSaid`), a refusal
 * (`needsRefused`) and the card's times are goldens too. The phone's port (the kit's `NeedsCard`) is held to the same
 * files, copied to `Tests/FieldProductTests/Fixtures/needs-card/` and pinned byte for byte by `pnpm check:ios-fixtures`.
 * A change to the card changes a golden here, and the kit's row is red until the port follows.
 *
 * The items are the contracts' own `needs-item.*` fixtures, every kind with the unknown one, each written into the
 * golden whole, so the kit reads the same item it decodes. The catalog's label for a held spawn's agent is written as
 * the card read it (`labels`): the kit hands its own catalog's label in, and its row holds the two to each other.
 *
 * `VF_WRITE_GOLDENS=1` writes the files; without it, each file must equal what the card says now, byte for byte.
 */

import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import {
  AGENT_CATALOG,
  type AgentFieldRow,
  type NeedsItem,
  type SparkSummary,
} from "@vibefield/contracts";
import { describe, expect, it } from "vitest";
import {
  NEEDS_FADE_MS,
  NEEDS_LEAVE_MS,
  NEEDS_SAID_MS,
  type NeedsCard,
  needsCardOf,
  needsCardWords,
  needsRefused,
  needsSaid,
  waitingCardOf,
} from "../src/chat/needs-card";
import { type SparkEntry, sparkEntriesOf } from "../src/chat/spark-status";

const here = dirname(fileURLToPath(import.meta.url));
const GOLDENS = join(here, "fixtures/needs-card");
const WRITE = process.env.VF_WRITE_GOLDENS === "1";
const GENERATED =
  "GENERATED by packages/field-app/test/needs-card-goldens.test.ts (VF_WRITE_GOLDENS=1): edit the case there, never here";

/** One of the contracts' needs-item fixtures, as fieldd hands it. */
const fixture = (name: string): NeedsItem =>
  JSON.parse(
    readFileSync(join(here, "../../contracts/fixtures", `needs-item.${name}.json`), "utf8"),
  ) as NeedsItem;

/** A golden as the generator writes it: two-space JSON and a final newline, formatted by nothing else. */
const textOf = (golden: unknown): string => `${JSON.stringify(golden, null, 2)}\n`;

/** Written under `VF_WRITE_GOLDENS=1`; else the committed file must be what the card says now, byte for byte. */
function holds(file: string, golden: unknown): void {
  const path = join(GOLDENS, file);
  const text = textOf(golden);
  if (WRITE) {
    mkdirSync(GOLDENS, { recursive: true });
    writeFileSync(path, text);
  }
  expect(readFileSync(path, "utf8"), `${file} is not what the card says now`).toBe(text);
}

// ── the spark ──

/** The fixtures' spark, and the run that is its own session (`from.session` of its own items). */
const VELA = "sp-7k2m9q4x";
const OWN_RUN = "run-12";
const AT = "2026-11-04T23:00:00.000Z";

const SPARK: SparkSummary = {
  id: VELA,
  name: "Vela",
  face: { seed: 4242 },
  agent: "claude",
  profiles: ["this-mac"],
  thinksUnder: "this-mac",
  folder: "/f/vela",
  createdAt: "2026-11-02T09:00:00.000Z",
  updatedAt: AT,
  session: { runtimeRunId: OWN_RUN, terminalSessionId: "pty-1", live: true },
};

/** Vela's own run on the board, alive and idle. */
const ROW: AgentFieldRow = {
  runtimeRunId: OWN_RUN,
  spark: VELA,
  revision: 1,
  kind: "claude",
  label: "Claude Code",
  tier: "managed",
  device: "dev-1",
  status: "idle",
  statusSince: AT,
  stateChangedAt: AT,
  createdAt: AT,
  alive: true,
  blockers: [],
};

/** Vela's entry with `items` in the queue, oldest first, as Chat's list reads it. */
function entryOf(items: readonly NeedsItem[]): SparkEntry {
  const entry = sparkEntriesOf([SPARK], [ROW], { items: [...items] })[0];
  if (entry === undefined) throw new Error("no entry");
  return entry;
}

/** What the card reads of the entry, and nothing else: the kit's port takes these. */
const entryFacts = (entry: SparkEntry) => ({
  spark: { id: entry.spark.id, name: entry.spark.name },
  ownRuns: entry.ownRuns,
  items: entry.items,
});

/** The card's facts, beside its words. */
const cardFacts = (card: NeedsCard) => ({
  own: card.own,
  of: card.of,
  waits: card.waits,
  names: card.names,
});

/** The catalog's label for each agent an item names (a lookup, never a literal: R23b). */
function labelsOf(items: readonly NeedsItem[]): Record<string, string> {
  const labels: Record<string, string> = {};
  for (const item of items) {
    if (item.agent === undefined) continue;
    const label = AGENT_CATALOG.find((entry) => entry.id === item.agent)?.label;
    if (label !== undefined) labels[item.agent] = label;
  }
  return labels;
}

// ── the items ──

const KINDS = [
  "question",
  "held-send",
  "held-send-cut",
  "held-spawn",
  "agent-ask",
  "flow-proposal",
  "flow-gate",
  "flow-changed",
  "flow-repair",
  "flow-cap",
  "flow-lost",
  "unknown-kind",
] as const;

/** `item` without the fields named: what fieldd says when it has no such fact. */
function without(item: NeedsItem, ...keys: readonly string[]): NeedsItem {
  return Object.fromEntries(
    Object.entries(item).filter(([key]) => !keys.includes(key)),
  ) as unknown as NeedsItem;
}

/** Vela's own run's ask (TH-Q29 (a)): an agent's ask whose session is her own run. */
const OWN_ASK: NeedsItem = {
  ...fixture("agent-ask"),
  id: "ny-0wn0a5k0vela",
  from: { name: "Claude Code", session: OWN_RUN },
};

/** An agent Vela started asks a question. */
const AGENT_QUESTION: NeedsItem = without(
  { ...fixture("agent-ask"), id: "ny-a9e7q0e5t10n", ask: "question" },
  "tool",
);

/** An agent's permission that names no tool. */
const AGENT_UNNAMED: NeedsItem = without(
  { ...fixture("agent-ask"), id: "ny-a9e7n0t00l00" },
  "tool",
);

/** A held spawn whose agent fieldd names without a folder, and one whose live count is unknown. */
const SPAWN_NO_FOLDER = without({ ...fixture("held-spawn"), id: "ny-5pawn0f01der" }, "folder");
const SPAWN_NO_LIVE = without({ ...fixture("held-spawn"), id: "ny-5pawn0l1ve00" }, "live");

/** A held send with one held word, and one that names no session. */
const SEND_ONE: NeedsItem = { ...fixture("held-send"), id: "ny-5end0ne00000", count: 1 };
const SEND_NO_TO = without({ ...fixture("held-send"), id: "ny-5end0t000000" }, "to");

interface WordsCase {
  readonly name: string;
  readonly about: string;
  /** the spark's open items, oldest first */
  readonly items: readonly NeedsItem[];
  /** the item the card draws (one of `items`, or one that has left the queue) */
  readonly item: NeedsItem;
}

const WORDS_CASES: readonly WordsCase[] = [
  ...KINDS.map((kind) => ({
    name: kind,
    about: `the contracts' needs-item.${kind} fixture, alone in Vela's queue`,
    items: [fixture(kind)],
    item: fixture(kind),
  })),
  {
    name: "own-ask",
    about: "Vela's own run's ask (TH-Q29 (a)): named by her name, the eyebrow the word alone",
    items: [OWN_ASK],
    item: OWN_ASK,
  },
  {
    name: "agent-question",
    about: "an agent Vela started has a question",
    items: [AGENT_QUESTION],
    item: AGENT_QUESTION,
  },
  {
    name: "agent-no-tool",
    about: "an agent's permission that names no tool",
    items: [AGENT_UNNAMED],
    item: AGENT_UNNAMED,
  },
  {
    name: "spawn-no-folder",
    about: "a held spawn whose agent has no folder",
    items: [SPAWN_NO_FOLDER],
    item: SPAWN_NO_FOLDER,
  },
  {
    name: "spawn-no-live",
    about: "a held spawn that does not say how many run",
    items: [SPAWN_NO_LIVE],
    item: SPAWN_NO_LIVE,
  },
  {
    name: "send-one",
    about: "a held send with one held word: no 'and N more'",
    items: [SEND_ONE],
    item: SEND_ONE,
  },
  {
    name: "send-no-to",
    about: "a held send that names no session",
    items: [SEND_NO_TO],
    item: SEND_NO_TO,
  },
  {
    name: "one-of-three",
    about: "the oldest of three that wait: its place is '1 of 3'",
    items: [fixture("question"), fixture("held-send"), fixture("held-spawn")],
    item: fixture("question"),
  },
  {
    name: "left-the-queue",
    about:
      "an item answered in another window, no longer in the queue: it counts itself and waits on no one",
    items: [fixture("held-send")],
    item: fixture("question"),
  },
];

function wordsGolden() {
  const items = WORDS_CASES.flatMap((wordsCase) => [...wordsCase.items, wordsCase.item]);
  return {
    "//": GENERATED,
    labels: labelsOf(items),
    cases: WORDS_CASES.map((wordsCase) => {
      const entry = entryOf(wordsCase.items);
      const card = needsCardOf(entry, wordsCase.item);
      return {
        name: wordsCase.name,
        about: wordsCase.about,
        entry: entryFacts(entry),
        item: wordsCase.item,
        card: cardFacts(card),
        words: needsCardWords(card),
      };
    }),
  };
}

// ── the order a thread stands its cards in ──

interface OrderCase {
  readonly name: string;
  readonly about: string;
  readonly items: readonly NeedsItem[];
}

const ORDER_CASES: readonly OrderCase[] = [
  { name: "none", about: "nothing waits: no card", items: [] },
  {
    name: "oldest",
    about: "a question and a held send: the oldest first",
    items: [fixture("question"), fixture("held-send")],
  },
  {
    name: "own-ask-first",
    about: "what holds its own run comes first, whatever is older (CO-Q12 (b), TH-1)",
    items: [fixture("question"), fixture("held-send"), OWN_ASK],
  },
  {
    name: "agent-ask-in-order",
    about: "an agent's ask that is not its own run's waits its turn",
    items: [fixture("agent-ask"), fixture("question")],
  },
];

function orderGolden() {
  return {
    "//": GENERATED,
    cases: ORDER_CASES.map((orderCase) => {
      const entry = entryOf(orderCase.items);
      const card = waitingCardOf(entry);
      return {
        name: orderCase.name,
        about: orderCase.about,
        entry: entryFacts(entry),
        card:
          card === null
            ? null
            : { item: card.item.id, ...cardFacts(card), place: needsCardWords(card).place },
      };
    }),
  };
}

// ── what an answer came to ──

/** An answer's facts as a case gives them; its time is the cases' own. Named here, since `Omit` over the contract's
 * passthrough type keeps no named key. */
interface AnswerFacts {
  readonly choice: number;
  readonly outcome: string;
  readonly told: boolean;
  readonly reason?: string;
  readonly waits?: string;
}

const answered = (item: NeedsItem, answer: AnswerFacts): NeedsItem => ({
  ...item,
  state: "answered",
  answer: { at: AT, ...answer },
});

interface SaidCase {
  readonly name: string;
  readonly about: string;
  /** the item fieldd handed back, with its answer */
  readonly item: NeedsItem;
  /** the act pressed, by its place */
  readonly choice: number;
}

const SAID_CASES: readonly SaidCase[] = [
  {
    name: "done",
    about: "a question answered, its spark told",
    item: answered(fixture("question"), { choice: 0, outcome: "done", told: true }),
    choice: 0,
  },
  {
    name: "unheard",
    about: "its spark sleeps and could not be woken yet: it hears it when it wakes",
    item: answered(fixture("question"), {
      choice: 1,
      outcome: "done",
      told: false,
      waits: "Vela's session ended before it took this",
    }),
    choice: 1,
  },
  {
    name: "unheard-no-why",
    about: "not told yet, with no words for why",
    item: answered(fixture("question"), { choice: 1, outcome: "done", told: false }),
    choice: 1,
  },
  {
    name: "send-failed",
    about: "a held send's Allow that could not be done: its words to the session",
    item: answered(fixture("held-send"), {
      choice: 0,
      outcome: "failed",
      reason: "it ended",
      told: true,
    }),
    choice: 0,
  },
  {
    name: "send-failed-no-to",
    about: "a held send that names no session, failed",
    item: answered(SEND_NO_TO, { choice: 0, outcome: "failed", reason: "it ended", told: true }),
    choice: 0,
  },
  {
    name: "spawn-failed",
    about: "Allow one more that could not start the agent",
    item: answered(fixture("held-spawn"), {
      choice: 0,
      outcome: "failed",
      reason: "the agent's sign-in expired",
      told: true,
    }),
    choice: 0,
  },
  {
    name: "other-failed",
    about: "any other act that could not be done",
    item: answered(fixture("flow-gate"), {
      choice: 0,
      outcome: "failed",
      reason: "the run stopped",
      told: true,
    }),
    choice: 0,
  },
  {
    name: "failed-and-unheard",
    about: "both hold: the act's failure is said",
    item: answered(fixture("held-spawn"), {
      choice: 0,
      outcome: "failed",
      reason: "no slot",
      told: false,
      waits: "Vela is asleep",
    }),
    choice: 0,
  },
  {
    name: "unknown-outcome",
    about: "an outcome this build does not know, told: what you said, alone",
    item: answered(fixture("question"), { choice: 2, outcome: "deferred", told: true }),
    choice: 2,
  },
  {
    name: "no-answer-yet",
    about: "the item as pressed, no answer recorded: the pressed act's word",
    item: fixture("held-send"),
    choice: 1,
  },
];

function saidGolden() {
  return {
    "//": GENERATED,
    times: { saidMs: NEEDS_SAID_MS, leaveMs: NEEDS_LEAVE_MS, fadeMs: NEEDS_FADE_MS },
    said: SAID_CASES.map((saidCase) => ({
      name: saidCase.name,
      about: saidCase.about,
      item: saidCase.item,
      choice: saidCase.choice,
      said: needsSaid(saidCase.item, saidCase.choice),
    })),
    refused: ["the item was answered", "UNAVAILABLE: no home answers"].map((reason) => ({
      reason,
      said: needsRefused(reason),
    })),
  };
}

// ── the rows ──

describe("the needs-you card's goldens (IOS-12d Q1 (a)): what the Mac's card says, for the phone's port", () => {
  it("the words, item by item", () => {
    holds("needs-card.words.golden.json", wordsGolden());
  });

  it("the order a thread stands its cards in", () => {
    holds("needs-card.order.golden.json", orderGolden());
  });

  it("what an answer came to, a refusal, and the card's times", () => {
    holds("needs-card.said.golden.json", saidGolden());
  });
});
